/* 132 original instructor-study-guide questions and author-provided answers, transcribed from user's Nov 2026 Exam 2 PDF. These are SOURCE NOTES, not independently verified clinical protocols. */
window.VPQ_PHARM_EXAM2_OBJECTIVE_CARDS=[{"id":"exam2-objective-001","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":1,"q":"Most likely type of DM in dogs and cats?","answer":"Dogs: Type 1 (lack of insulin; adult-onset, irreversible, immune-mediated damage to the pancreas). Cats: Type 2 (insulin receptors desensitized, mostly by obesity; 60% of diabetic cats are obese). Exception: cats can get Type 1 from pancreatitis or tumors, and long hyperglycemia kills their beta cells (Type 2 becomes Type 1).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":1},{"id":"exam2-objective-002","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":2,"q":"Two goals of DM treatment in dogs?","answer":"(1) Eliminate the clinical signs and make them happy. (2) Prevent short-term complications: DKA and hypoglycemia. Remission is rare in dogs because the beta cells are already destroyed.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":2},{"id":"exam2-objective-003","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":3,"q":"Primary goal of DM treatment in cats?","answer":"Remission, most likely in the first 6 months before hyperglycemia kills the beta cells.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":3},{"id":"exam2-objective-004","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":4,"q":"Amorphous vs crystalline insulin?","answer":"Amorphous = individual insulin molecules in a non-coordinated state, absorbed readily (regular insulin). Crystalline = molecules in a coordinated state, which slows absorption from the injection site.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":4},{"id":"exam2-objective-005","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":5,"q":"How do protamine, zinc and myristic acid change absorption?","answer":"Protamine: excipient protein that binds insulin so it crystallizes (isophane = dilute protamine). Zinc: crystallizes insulin into hexamers, slowing absorption. Myristic acid: attached to the insulin; after the injection it binds albumin, and the insulin leaks slowly off the albumin complex.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":5},{"id":"exam2-objective-006","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":6,"q":"Short-acting insulin used in vet med, and when?","answer":"Regular insulin (Humulin R), which has no excipients. Used for DKA and other hyperglycemic crises, IV as a constant- rate infusion or IM. Never SQ: dehydrated patients do not absorb it reliably.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":6},{"id":"exam2-objective-007","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":7,"q":"Know: starting drugs for dogs","answer":"Intermediate-acting insulins (NPH, Vetsulin) are the starting drugs for dogs. They are not first choices in cats.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":7},{"id":"exam2-objective-008","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":8,"q":"Know: \"Lente\"","answer":"Intermediate-acting insulins are sometimes called Lente (zinc-acetate preparations such as Vetsulin).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":8},{"id":"exam2-objective-009","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":9,"q":"Know: syringe matching","answer":"Match the syringe to the concentration: U40 syringe for 40 U/mL (Vetsulin, PZI) vs U100 syringe for 100 U/mL.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":9},{"id":"exam2-objective-010","lecture":"Lecture 10","section":"Anti-diabetes drugs (Diabetes 1)","number":10,"q":"Know: Vetsulin handling","answer":"Vetsulin must be shaken vigorously. All other preparations are only rolled gently.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":10},{"id":"exam2-objective-011","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":1,"q":"Name the five long-acting insulins.","answer":"Ultralente, PZI, Glargine, Detemir, Degludec.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":11},{"id":"exam2-objective-012","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":2,"q":"Unusual solubility of glargine and what it means for dilution?","answer":"Glargine's pI is 5.4 (insulin 6.7). It is made at pH 4, where it is 95% soluble. At tissue pH 7.4 it is only about 5% soluble, so it precipitates and slowly leaks out. Do not dilute casually, because changing the pH ruins this. Use the manufacturer's specific diluent.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":12},{"id":"exam2-objective-013","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":3,"q":"Caveat with detemir in dogs?","answer":"Detemir has 4× lower affinity for the human insulin receptor, so the human product is 4× concentrated. But its affinity for the canine receptor is normal, so the same dose can cause hypoglycemic crises in dogs.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":13},{"id":"exam2-objective-014","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":4,"q":"Why are clinical signs not enough to avoid hypoglycemia in cats on long- acting insulin?","answer":"Glargine and detemir cause nocturnal nadirs, which is useful because owners are home to see signs. But cats can be hypoglycemic without clinical signs.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":14},{"id":"exam2-objective-015","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":5,"q":"Current insulin recommendations for dogs and cats?","answer":"Dogs: NPH or Vetsulin first (glargine U300 if once daily is a must). Cats: glargine (best first choice now), detemir or PZI. Start with twice-daily dosing. Dogs are dosed per kg, cats per cat.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":15},{"id":"exam2-objective-016","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":6,"q":"Ultimate therapeutic goal for diabetic cats?","answer":"Remission.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":16},{"id":"exam2-objective-017","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":7,"q":"Why is hypoglycemia especially concerning in pets?","answer":"It is often life-threatening and pets cannot get an appropriate snack on their own. (It may be a risk you accept in cats when remission is the goal.)","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":17},{"id":"exam2-objective-018","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":8,"q":"Somogyi effect: what, how to detect, what to do?","answer":"A rebound from insulin overdose: a rapid fall in glucose triggers glucose release (a hypoglycemia-hyperglycemia roller coaster). Pattern: 1–2 days of good control then several days of poor control. Detect with a blood glucose curve in dogs (stress ruins it in cats; fructosamine avoids the stress). Reduce the dose and re-evaluate in 2–5 days.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":18},{"id":"exam2-objective-019","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":9,"q":"Why do acromegaly or sexual \"intactness\" complicate DM treatment?","answer":"Acromegaly: excess somatotropin from a pituitary tumor is diabetogenic (more hepatic gluconeogenesis). Needs up to 40 U of insulin; levels are pulsatile and sporadically drop, causing sudden hypoglycemia. Octreotide, pasireotide and pegvisomant have been tried; usually fatal within a year. Intactness: his slide lists \"reproductive issues\" as an underlying cause of poor control.  ➕    The standard mechanism is insulin resistance driven by reproductive hormones, which is why spaying is part of the plan.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":19},{"id":"exam2-objective-020","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 2)","number":10,"q":"Why can renal disease change DM treatment?","answer":"The kidneys clear insulin (proteolysis), so in a patient with renal disease exogenous insulin lasts longer. This can even help stretch an inexpensive intermediate insulin like NPH in a dog.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":20},{"id":"exam2-objective-021","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 3)","number":1,"q":"What is used to treat DKA?","answer":"Fluids and electrolytes first (correct Na⁺, K⁺ and phosphate; insulin can worsen hypokalemia), then regular insulin as a CRI or IM every 4–6 h, never SQ. Dump the first 50–100 mL of the CRI (insulin sticks to the bag and tubing). Lower glucose slowly (50 mg/dL/h) or the Somogyi effect follows. At 250 mg/dL slow the rate. Start a longer-acting insulin once stable and eating.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":21},{"id":"exam2-objective-022","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 3)","number":2,"q":"Know: non-insulin drugs","answer":"Used for (1) cats whose owners refuse insulin but will not euthanize, (2) an adjunct to insulin in refractory dogs, (3) post-remission cats that need to stay on a normal-carb diet. Most need endogenous insulin, so cats respond better.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":22},{"id":"exam2-objective-023","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 3)","number":3,"q":"Dog with Somogyi on Vetsulin: next insulin?","answer":"A longer-duration insulin, PZI. The dose may be right but is released too fast. Use the same number of units and repeat the BG curve in about a week.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":23},{"id":"exam2-objective-024","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 3)","number":4,"q":"Why are prandial non-insulin drugs not recommended in cats?","answer":"Cats are unpredictable eaters, so drug timing around a meal does not match what they eat.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":24},{"id":"exam2-objective-025","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 3)","number":5,"q":"How is insulin used in bovine and equine DM-like diseases?","answer":"Cattle, negative-energy ketosis: propylene glycol (becomes propionic acid, a glucose precursor) plus a corticosteroid; if severe, IV glucose then PZI every other day. Fat cow ketosis (Type 2 DM): NPH twice daily plus IV glucose. Insulin suppresses fatty acid mobilization and increases glucose uptake. Horses (equine metabolic syndrome): not an insulin disease; treat with weight loss, low-carb diet, pre- soaked hay, metformin timed with feeding, and thyroid hormone.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":25},{"id":"exam2-objective-026","lecture":"Lecture 11","section":"Anti-diabetes drugs (Diabetes 3)","number":6,"q":"What is streptozotocin and when is it used?","answer":"An alkylating anticancer agent toxic to DNA, from Streptomyces in Blue Rapids, Kansas. It resembles glucose and enters islet cells through Glut2 (not Glut4), so it kills beta cells. Used for insulinoma: low dose every 4–6 weeks so some beta cells survive and insulin is not needed.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":26},{"id":"exam2-objective-027","lecture":"Lecture 12","section":"Thyroid drugs","number":1,"q":"How do the hypothalamus and anterior pituitary promote and regulate thyroid hormone synthesis?","answer":"The hypothalamus releases TRH, which makes the anterior pituitary release TSH, which stimulates the thyroid to make and release T3, T4 and calcitonin. TRH-R and TSH-R are GPCRs. TSH also turns on NIS (the iodide transporter) and thyroglobulin synthesis. T3 and T4 (mostly T4) give negative feedback on both TRH and TSH. Somatostatin inhibits TSH.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":27},{"id":"exam2-objective-028","lecture":"Lecture 12","section":"Thyroid drugs","number":2,"q":"Synthesis and release mechanisms for thyroid hormones?","answer":"Iodide enters the follicle cell through NIS (with Na⁺; perchlorate blocks NIS). Pendrin moves it into the follicle lumen. Thyroperoxidase iodinates tyrosines on thyroglobulin, making MIT and DIT. The iodinated thyroglobulin is taken back into the cell and proteases release the pieces: MIT + DIT = T3; DIT + DIT = T4. They are released to plasma, mostly T4. In target cells T4 is mono-deiodinated to T3, which binds the T3 receptor with the RXR co-receptor.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":28},{"id":"exam2-objective-029","lecture":"Lecture 12","section":"Thyroid drugs","number":3,"q":"Name three drugs that can cause pseudohypothyroidism.","answer":"Glucocorticoids (low T4, normal TSH; adjust the dose if possible), phenobarbital (low T4, possible TSH rise; no worry about true hypothyroidism), sulfonamide antibiotics (T3 and T4 low, TSH high; true hypothyroidism if used long-term). His slide also lists carprofen. Other causes: sick euthyroid syndrome, and sighthounds and northern breeds.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":29},{"id":"exam2-objective-030","lecture":"Lecture 12","section":"Thyroid drugs","number":4,"q":"Treatment of hypothyroidism in dogs, cats and horses?","answer":"Levothyroxine (T4) in all three, given on an empty stomach in dogs. Dogs: the most common species; T4 is the gold standard. T3 is not used clinically because only T4 gives negative feedback. Cats: rare; iatrogenic (after treating hyperthyroidism) or cretinism. Horses: rare, verify low T4 with high TSH first; T4 is also used to speed weight loss in EMS. Poor response: outdated tablets, or switching brands (different bioavailability).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":30},{"id":"exam2-objective-031","lecture":"Lecture 12","section":"Thyroid drugs","number":5,"q":"Treatments for feline hyperthyroidism?","answer":"Four options: (1) Y/D low-iodine diet for non-severe cases (over 80% remission, poor palatability, cheapest). (2) Methimazole, which inhibits thyroperoxidase so less MIT and DIT; cheap, transdermal form exists, good for geriatric cats; monitor CBC, T4, platelets, BUN and creatinine, liver enzymes. PTU and carbimazole work the same but have more side effects. (3) I¹³¹, the most effective and most expensive ($2,200–$2,700); start methimazole first to stabilize and check metabolic, CV and renal function; stop methimazole and Y/D 10–14 days before; radiation precautions after; may need T4 afterward. (4) Thyroidectomy, pretreat with methimazole; risks are ectopic tissue left behind, needing T4, and parathyroid damage.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":31},{"id":"exam2-objective-032","lecture":"Lecture 12","section":"Thyroid drugs","number":6,"q":"Treatment of hypoparathyroidism and milk fever?","answer":"Hypoparathyroidism (after thyroidectomy or innate): oral calcium lactate or carbonate plus calcitriol. Milk fever: IV calcium borogluconate; if the cow will not rise once calcium is normal, tripelennamine or hypertonic saline. Prevention: anionic salts (Cl and S) in the dry period, which sequester dietary calcium and so activate PTH.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":32},{"id":"exam2-objective-033","lecture":"Lecture 13","section":"Autonomic pharmacology","number":1,"q":"Major NT of the PNS?","answer":"Acetylcholine (at both synapses).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":33},{"id":"exam2-objective-034","lecture":"Lecture 13","section":"Autonomic pharmacology","number":2,"q":"Major effector NTs of the SNS at the organ?","answer":"Norepinephrine and epinephrine (adrenergic).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":34},{"id":"exam2-objective-035","lecture":"Lecture 13","section":"Autonomic pharmacology","number":3,"q":"NT common to SNS and PNS?","answer":"Acetylcholine (ganglionic synapse in both; also the SNS nerve to the adrenal medulla chromaffin cells, the only ANS nerve with no ganglion).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":35},{"id":"exam2-objective-036","lecture":"Lecture 13","section":"Autonomic pharmacology","number":4,"q":"Seven major ANS receptors?","answer":"Nicotinic (ion channel; ganglia and NMJ), muscarinic (GPCR at the effector), and adrenergic α1, α2, β1, β2, β3 (all GPCRs). α2 is covered in neuropharmacology.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":36},{"id":"exam2-objective-037","lecture":"Lecture 13","section":"Autonomic pharmacology","number":5,"q":"To prevent urination: which SNS receptor to activate and which PNS receptor to inhibit?","answer":"Activate α1 (sphincter contraction; β1 also relaxes the bladder wall) and inhibit the muscarinic receptor. Drugs: phenylpropanolamine (α1 and β1 agonist, some CV effects); oxybutynin (muscarinic antagonist, semi-selective for bladder, fewer CV but more GI effects).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":37},{"id":"exam2-objective-038","lecture":"Lecture 13","section":"Autonomic pharmacology","number":6,"q":"To promote urination: which PNS receptor to activate and which SNS receptor to inhibit?","answer":"Activate the muscarinic receptor and inhibit α1. Drugs: bethanechol (muscarinic agonist), prazosin, tamsulosin, phenoxybenzamine (α1 antagonists).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":38},{"id":"exam2-objective-039","lecture":"Lecture 13","section":"Autonomic pharmacology","number":7,"q":"To promote mydriasis: SNS receptor to activate, PNS receptor to inhibit?","answer":"Activate α1 and inhibit the muscarinic receptor. Drugs: phenylephrine, tropicamide, atropine.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":39},{"id":"exam2-objective-040","lecture":"Lecture 13","section":"Autonomic pharmacology","number":8,"q":"To promote miosis: PNS receptor to activate, SNS receptor to inhibit?","answer":"Activate the muscarinic receptor and inhibit α1. Drugs: pilocarpine, demecarium bromide.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":40},{"id":"exam2-objective-041","lecture":"Lecture 13","section":"Autonomic pharmacology","number":9,"q":"MOAs and uses of the listed drugs","answer":"Phenylpropanolamine: non-selective α1 and β1 agonist; urine retention (incontinence); some CV side effects. Oxybutynin: muscarinic antagonist, bladder-selective; urine retention; fewer CV, more GI effects. Prazosin: non- selective α1 antagonist; promotes urination; some CV effects. Tamsulosin: selective α1 antagonist; urethrospasm from urethritis or urethroliths. Phenoxybenzamine: irreversible α1 antagonist; mainly for pheochromocytoma hypertension (urination is a side effect). Bethanechol: muscarinic agonist; promotes urination; contraindicated if the bladder wall is compromised or after urethral obstruction. Tropicamide: muscarinic antagonist; short-acting mydriatic for eye exams. Atropine: muscarinic antagonist; long-acting; ocular comfort and less posterior synechia in uveitis; very long half-life in horses (colic risk); use ointment in cats (drops cause hypersalivation); contraindicated in glaucoma and KCS. Phenylephrine: α1 agonist; mydriasis, sometimes combined with tropicamide or atropine. Pilocarpine and demecarium bromide: muscarinic agonists; miotics for glaucoma (unless secondary to lens luxation) and lens instability. Succinylcholine: activates the nicotinic receptor at the NMJ and is not broken down by AChE, so it overstimulates it; flaccid paralysis, then diaphragm paralysis at higher doses; used for euthanasia in wildlife and equine castration.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":41},{"id":"exam2-objective-042","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":1,"q":"Mechanistic goal of anti-CHF drugs?","answer":"Raise intra-myocytic calcium so contractility improves.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":42},{"id":"exam2-objective-043","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":2,"q":"MOAs of the five anti-CHF drugs?","answer":"Digoxin: inhibits the Na⁺/K⁺ ATPase, so Na⁺ builds up, the Na⁺/Ca²⁺ exchanger runs in reverse, and Ca²⁺ rises. Dopamine: D1 agonist, so adenylyl cyclase makes cAMP, which mobilizes Ca²⁺. Dobutamine: β1 agonist, same cAMP path. Amrinone: PDE3 inhibitor, so cAMP rises. Pimobendan: PDE3 inhibitor plus calcium sensitizer (binds troponin C and raises its affinity for Ca²⁺).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":43},{"id":"exam2-objective-044","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":3,"q":"Which anti-CHF drug is also a vasodilator?","answer":"Pimobendan (an \"inodilator\"); it opens a K⁺ channel in vascular smooth muscle. Approved only in dogs.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":44},{"id":"exam2-objective-045","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":4,"q":"Which is more likely to be toxic if the patient is hypokalemic?","answer":"Digoxin. Many diuretics cause hypokalemia, and diuretics are often given with digoxin.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":45},{"id":"exam2-objective-046","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":5,"q":"Common toxicity of all anti-CHF drugs?","answer":"Arrhythmias. For digoxin also AV block, PVCs, pulsus bigeminy, Vfib, GI signs. Treat by stopping the drug, treating the arrhythmia, IV fluids for renal clearance, and careful K⁺ if hypokalemic.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":46},{"id":"exam2-objective-047","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":6,"q":"Two drugs for ventricular ectopic beats, and their MOA?","answer":"Lidocaine and mexiletine: Na⁺ channel blockers that bind rapidly and selectively to refractory channels. Lidocaine is IV for acute ventricular arrhythmias; mexiletine is an oral syrup for long-term use. Not for atrial problems. ⚠ His Class 4 slide also lists premature ectopic beats (esp. PVCs) as the main use of verapamil and diltiazem.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":47},{"id":"exam2-objective-048","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":7,"q":"Which anti-arrhythmic causes corneal deposits, and its MOA?","answer":"Amiodarone (Class 3): blocks K⁺ and Ca²⁺ channels and prolongs the refractory period. Also pulmonary fibrosis and GI upset; contraindicated if bradycardic.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":48},{"id":"exam2-objective-049","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":8,"q":"Two anti-arrhythmics that selectively bind refractory Na⁺ channels?","answer":"Lidocaine and mexiletine.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":49},{"id":"exam2-objective-050","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":9,"q":"Preferred drug for long-term oral treatment of V-tach and ventricular arrhythmias, and its MOA?","answer":"Procainamide: Class I Na⁺ channel blocker with moderate association and dissociation, non-selective for open vs refractory channels. Halve the dose with renal disease. Contraindicated for conduction block.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":50},{"id":"exam2-objective-051","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":10,"q":"Cat with hyperthyroid arrhythmia: which drug, MOA?","answer":"Propranolol: a non-selective β blocker; blocking β1 lowers excitation and rate. Raise the dose slowly to avoid bronchospasm (anti-β2).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":51},{"id":"exam2-objective-052","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":11,"q":"Cat with hyperthyroid hypertension without arrhythmia: which drug, MOA?","answer":"Amlodipine: Ca²⁺ channel blocker (same MOA as diltiazem), so less Ca²⁺ in vascular smooth muscle, vasodilation, lower pressure. Front-line for feline hypertension.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":52},{"id":"exam2-objective-053","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":12,"q":"Hydralazine MOA, why emergency-only, and the other emergency drug?","answer":"Hydralazine: blocks Ca²⁺ release from the sarcoplasmic reticulum, increases smooth muscle sensitivity to NO, and opens a K⁺ channel. Emergency-only because it can drop pressure enough to trigger the baroreflex and tachycardia with extended use. Sodium nitroprusside donates NO, activating the NANC pathway, so vasodilation.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":53},{"id":"exam2-objective-054","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":13,"q":"How does telmisartan lower blood pressure?","answer":"It antagonizes the angiotensin II (AT1) receptor, which ultimately raises NO and causes vasodilation. FDA-approved for feline hypertension; also reduces proteinuria.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":54},{"id":"exam2-objective-055","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":14,"q":"Two ACE inhibitors, how they treat hypertension, how they assist anti-CHF drugs?","answer":"Enalapril and benazepril. They block ACE (angiotensin I to II), so less AT1 activation and vasodilation. Less angiotensin II means less aldosterone, so diuresis and a lower fluid load, which helps CHF. They offset the rise in blood pressure that anti- CHF drugs cause by increasing cardiac output.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":55},{"id":"exam2-objective-056","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":15,"q":"Drug for pulmonary hypertension and MOA?","answer":"Sildenafil, a PDE5 inhibitor. More cGMP, so PKG opens a Ca²⁺-lowering channel and vascular smooth muscle stays relaxed.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":56},{"id":"exam2-objective-057","lecture":"Lecture 14","section":"Cardiovascular pharmacology","number":16,"q":"Mainstay drug for cardiac resuscitation?","answer":"Epinephrine (adrenaline). Atropine, bicarbonate, calcium, magnesium and fibrinolytics only in specific circumstances.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":57},{"id":"exam2-objective-058","lecture":"Lecture 15","section":"Respiratory pharmacology","number":1,"q":"Three facets controlling airway tone, and how two can be manipulated?","answer":"Parasympathetic (ACh at M3 receptors; baseline mild bronchoconstriction), sympathetic (β2 receptors cause bronchodilation; α receptors constrict), and NANC (nitric oxide via vagal fibers; bronchodilation, but hard to manipulate). Bronchodilate by activating β2 (β agonists) or blocking muscarinic receptors (anticholinergics).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":58},{"id":"exam2-objective-059","lecture":"Lecture 15","section":"Respiratory pharmacology","number":2,"q":"Types, names and selectivities of β agonists?","answer":"Non-selective (β1 and β2): epinephrine, ephedrine, isoproterenol; α activity adds vasoconstriction and hypertension. Selective β2: terbutaline (oral or parenteral; cat asthma), albuterol (oral, aerosol; also lowers serum K⁺, useful for urinary obstruction), clenbuterol (equine syrup, lasts 6–8 h). Isoetharine is nebulized and not β2-selective; pirbuterol, salmeterol, formoterol are inhaled.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":59},{"id":"exam2-objective-060","lecture":"Lecture 15","section":"Respiratory pharmacology","number":3,"q":"Methylxanthines and how they bronchodilate?","answer":"Theophylline and aminophylline (aminophylline is used in small animals). They inhibit phosphodiesterase, so cAMP is not broken down; they also interfere with Ca²⁺ mobilization and block adenosine receptors. Side effects: CNS excitation, vomiting, diuresis, tachycardia; slow-release products preferred.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":60},{"id":"exam2-objective-061","lecture":"Lecture 15","section":"Respiratory pharmacology","number":4,"q":"Issues with clenbuterol and zilpaterol in horses and cattle?","answer":"Clenbuterol: approved in horses (Ventipulmin); high doses activate β1 (tachycardia, excitement, sweating). Abused in racehorses (ARCI class 3) though it gives a healthy horse no cardiopulmonary advantage; chronic use repartitions toward muscle. Banned as a feed additive. Zilpaterol (Zilmax): cattle growth promoter withdrawn voluntarily because of health problems including lameness; highly toxic to horses.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":61},{"id":"exam2-objective-062","lecture":"Lecture 15","section":"Respiratory pharmacology","number":5,"q":"Recognize an anticholinergic bronchodilator","answer":"Atropine (acutely dyspneic animal; tachycardia, ileus, less mucociliary clearance), ipratropium (better bronchodilator, does not cross the blood- brain barrier, poorly absorbed from aerosol), glycopyrrolate (slower onset, longer half-life).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":62},{"id":"exam2-objective-063","lecture":"Lecture 15","section":"Respiratory pharmacology","number":6,"q":"Recognize expectorants, peripheral and central antitussives","answer":"Expectorant: potassium iodide (guaifenesin and ambroxol also ease coughing up secretions). Peripheral: expectorants, and bronchodilators like ephedrine and theophylline that relieve irritant receptor stimulation. Central narcotic: codeine, hydrocodone, butorphanol (sedation, constipation). Central non-narcotic: dextromethorphan. Do not suppress a cough unless it is excessive or debilitating.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":63},{"id":"exam2-objective-064","lecture":"Lecture 15","section":"Respiratory pharmacology","number":7,"q":"Actions and uses of doxapram and thioredoxin","answer":"Doxapram: IV respiratory stimulant; activates carotid body chemoreceptors, which stimulate the brainstem respiratory center; used peri-surgically and can reverse opioid respiratory depression. Thioredoxin: protein disulfide reductase that breaks disulfide links in mucins (excess mucus) and activates β- defensins; a nebulized lung-specific analog is a potential treatment for BRD and heaves.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":64},{"id":"exam2-objective-065","lecture":"Lecture 15","section":"Respiratory pharmacology","number":8,"q":"Which antibiotics are good for respiratory infections?","answer":"BRD metaphylaxis: tulathromycin, gamithromycin, tildipirosin, tilmicosin. BRD treatment: florfenicol ± flunixin, ceftiofur, enrofloxacin, danofloxacin, pradofloxacin, tulathromycin + ketoprofen. Dairy cattle, calves, swine, horses: ceftiofur. Dogs and cats: amoxicillin + clavulanate.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":65},{"id":"exam2-objective-066","lecture":"Lecture 16","section":"Renal pharmacology (diuretics)","number":1,"q":"When to use diuretics?","answer":"To make a large volume of dilute urine and shrink extracellular fluid volume. Used where extra ECF is harmful: CHF (pulmonary edema and dyspnea), hepatic disease (ascites, low protein edema), renal disease with Na⁺ retention, equine exercise-induced pulmonary hemorrhage. Oliguric acute renal failure is only a palliative attempt and may do harm.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":66},{"id":"exam2-objective-067","lecture":"Lecture 16","section":"Renal pharmacology (diuretics)","number":2,"q":"Where do the different classes work, and what does that mean for strengths and weaknesses?","answer":"Proximal tubule: osmotic diuretics (mannitol) and carbonic anhydrase inhibitors. Thick ascending limb: loop diuretics (NKCC2). Late distal tubule: thiazides (Na-Cl symporter). Collecting duct: spironolactone, K⁺-sparing diuretics, aquaretics. Most water (70%) is reabsorbed in the proximal tubule, but the nephron downstream can compensate; later sites give weaker diuresis. Knowing the site explains each drug's limits and why drugs are combined (sequential blockade).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":67},{"id":"exam2-objective-068","lecture":"Lecture 16","section":"Renal pharmacology (diuretics)","number":3,"q":"Adverse effects of diuretics as a class, and why?","answer":"Hypovolemia (less Na⁺ and water retained), pre-renal azotemia (low volume lowers renal blood flow, BUN rises), electrolyte loss (Na⁺, Cl⁻, K⁺, and indirectly Mg²⁺ and Ca²⁺), metabolic alkalosis (preferential Cl⁻ loss). Hypokalemia: extra Na⁺ reaches the late distal tubule and eNaC swaps it for K⁺. Manage by monitoring (owner checks CRT; bloodwork at 24–48 h and 7–14 days), supplementing fluids and electrolytes, and using the lowest effective dose.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":68},{"id":"exam2-objective-069","lecture":"Lecture 16","section":"Renal pharmacology (diuretics)","number":4,"q":"Why is furosemide such an effective diuretic?","answer":"It inhibits NKCC2 (Na⁺/K⁺/2Cl⁻) in the thick ascending limb, so solutes stay in the lumen and water follows. Potent, high ceiling, safe, fast (30 min IV, 2 h oral), cheap, many routes, works in all five major species. Downsides: short duration (4–5 h), reversible ototoxicity, and a \"braking\" effect (volume loss triggers RAAS). Uses: CHF, equine EIPH, hypertension, edema, and preparturient udder edema (drug of choice since it will not induce parturition; 48 h milk withhold).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":69},{"id":"exam2-objective-070","lecture":"Lecture 16","section":"Renal pharmacology (diuretics)","number":5,"q":"Disadvantages of furosemide and why torsemide might be better?","answer":"Torsemide (approved in dogs): more diuresis per mg, longer-acting, slower onset so smoother diuresis, and approved with pimobendan, spironolactone and an ACE inhibitor for CHF pulmonary edema. Catch: potency makes dosing hard to control (over- or under-diuresis).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":70},{"id":"exam2-objective-071","lecture":"Lecture 16","section":"Renal pharmacology (diuretics)","number":6,"q":"Spironolactone MOA, why no K⁺ wasting, and why its RAAS effect helps CHF?","answer":"It blocks the mineralocorticoid (aldosterone) receptor in the late distal tubule and collecting duct, so Na⁺ (and water) stay in the lumen and K⁺ is kept. It is a weak diuretic alone but pairs with loop diuretics to limit K⁺ loss (sequential blockade). It also limits aldosterone- driven inflammation and fibrosis, and stops aldosterone breakthrough when ACE inhibition is incomplete, so it controls ECF better with an ACE inhibitor. Cautions: hyperkalemia, raises digoxin half-life, not for food animals, male reproductive effects (anti-androgen).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":71},{"id":"exam2-objective-072","lecture":"Lecture 16","section":"Renal pharmacology (diuretics)","number":7,"q":"Lesser-used diuretics: MOA, uses, adverse effects","answer":"Osmotic (mannitol): inert glucose-like sugar that holds water in the proximal tubule; weak, IV only; emergency for high intraocular or intracranial pressure; adverse: rapid volume expansion and hypertension. Carbonic anhydrase inhibitors (acetazolamide): block Na⁺ retention path in the proximal tubule; glaucoma, edema, metabolic alkalosis; adverse: metabolic acidosis (avoid in pulmonary disease), uroliths from alkaline urine, hypokalemia. Thiazides: block the Na-Cl symporter in the late distal tubule; second choice behind loops for CHF; hydrochlorothiazide for cattle udder edema (72 h withhold); adverse: more Ca²⁺ reabsorption, impair anticoagulants and insulin, blunted by NSAIDs. K⁺- sparing (triamterene, amiloride): block eNaC; weak, seldom used alone, spironolactone is better; adverse: hyperkalemia.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":72},{"id":"exam2-objective-073","lecture":"Lecture 17","section":"GI pharmacology","number":1,"q":"MOAs of the three main anti-emetics?","answer":"Metoclopramide: D2 dopamine receptor antagonist. Maropitant: NK1 receptor antagonist (blocks visceral input to the CTZ and vestibular input). Ondansetron: 5-HT3 antagonist (also blocks serotonin release and vagal efferents).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":73},{"id":"exam2-objective-074","lecture":"Lecture 17","section":"GI pharmacology","number":2,"q":"Which stimulates gastric emptying, which is contraindicated with liver disease, which is reserved for refractory cases?","answer":"Metoclopramide stimulates gastric emptying (and is contraindicated with GI obstruction). Maropitant: caution with hepatic problems. Ondansetron: most potent, reserved for severe or refractory emesis.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":74},{"id":"exam2-objective-075","lecture":"Lecture 17","section":"GI pharmacology","number":3,"q":"Three pro-emesis drugs for dogs, two for cats, and their MOAs?","answer":"Dogs: ropinirole (D2 agonist eye drop; reverse with metoclopramide), apomorphine (D2 agonist; compounded), 3% hydrogen peroxide (gastric irritation; fresh each time; most side effects). Cats: hydromorphone (opioid) and low-dose xylazine (α2 agonist). Horses cannot vomit.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":75},{"id":"exam2-objective-076","lecture":"Lecture 17","section":"GI pharmacology","number":4,"q":"Prokinetic MOAs for metoclopramide, cisapride, H2 blockers, erythromycin?","answer":"Metoclopramide: D2 antagonist that stimulates gastric emptying. Cisapride: 5-HT4 agonist, so ACh release in the enteric PNS (human form pulled for long QT; now compounded; highly effective). H2 blockers (ranitidine and nizatidine only): anticholinesterase activity raises ACh. Erythromycin (sub-MIC dose): motilin receptor agonist, so ACh release and peristalsis. All prokinetics are contraindicated with GI obstruction.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":76},{"id":"exam2-objective-077","lecture":"Lecture 17","section":"GI pharmacology","number":5,"q":"Prokinetic MOAs for the three equine drugs?","answer":"Lidocaine CRI: blocks Na⁺ channels in the SNS, so PNS activation. Bethanechol: muscarinic agonist. Neostigmine: acetylcholinesterase inhibitor.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":77},{"id":"exam2-objective-078","lecture":"Lecture 17","section":"GI pharmacology","number":6,"q":"MOAs of the four anti-colic therapies?","answer":"Magnesium sulfate: osmotic agent for impactions (max 3 days in a row). Mineral oil: lubricant that prevents water reabsorption; ascarids, impactions, and a transit marker. Psyllium husk: sand impaction. Butylscopolammonium (Buscopan): muscarinic antagonist that relaxes GI muscle; gas or spasmodic colic and choke.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":78},{"id":"exam2-objective-079","lecture":"Lecture 17","section":"GI pharmacology","number":7,"q":"MOAs of the four anti-ulcer therapies, and the hierarchy?","answer":"In order: (1) Proton pump inhibitors (omeprazole oral, pantoprazole IV): irreversibly block the H⁺/K⁺ ATPase; first choice, especially with esophagitis. (2) Sucralfate: sticky cyto-adherent coating that also boosts prostaglandins; stagger from the PPI. (3) Misoprostol: PGE1 agonist (less acid, more bicarbonate and mucus); for NSAID ulcers; never in pregnancy (luteolysis). (4) H2 blockers: reversible; last resort (ranitidine and nizatidine inconsistent, famotidine tolerance in 48 h, cimetidine blocks drug metabolism).","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":79},{"id":"exam2-objective-080","lecture":"Lecture 17","section":"GI pharmacology","number":8,"q":"Three antibiotics for IBD?","answer":"Metronidazole, tylosin, sulfasalazine. Add psyllium during therapy to limit dysbiosis, then probiotics.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":80},{"id":"exam2-objective-081","lecture":"Lecture 17","section":"GI pharmacology","number":9,"q":"Two general anti-diarrheals and MOAs?","answer":"Bismuth salicylate (secretory diarrhea; salicylate is a COX inhibitor; not in cats) and activated charcoal (sequesters toxins). Kaolin/pectin may bind toxins and bacteria but has weak evidence.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":81},{"id":"exam2-objective-082","lecture":"Lecture 17","section":"GI pharmacology","number":10,"q":"Why is cobalamin an adjunct for GI disease?","answer":"Chronic bacterial diarrhea (and pancreatic or liver disease) greatly reduces cobalamin absorption, and low cobalamin delays recovery. Give a 6- week SQ course, then recheck levels.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":82},{"id":"exam2-objective-083","lecture":"Lecture 17","section":"GI pharmacology","number":11,"q":"Anti-pancreatitis drug, how it works, and why it prevents a metabolic disease?","answer":"Fuzapladib (Panoquell-CA1): blocks LFA- 1, which otherwise draws neutrophils into the pancreas and worsens inflammation. Recurrent pancreatitis is a suspected risk factor for diabetes mellitus in dogs, so treating it may protect against DM.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":83},{"id":"exam2-objective-084","lecture":"Lecture 17","section":"GI pharmacology","number":12,"q":"Two nutraceuticals/botanicals for hepatic dysfunction and how they work?","answer":"SAMe scavenges free radicals that damage hepatocyte membranes. Milk thistle (silybin; combined with SAMe as Denamarin) is hepatoprotective. Both can be tried to prevent death cap mushroom toxicity if given right after ingestion.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":84},{"id":"exam2-objective-085","lecture":"Lecture 17","section":"GI pharmacology","number":13,"q":"How do copper chelators, UDA and acetylcysteine help specific liver problems?","answer":"Copper chelators: D-penicillamine promotes urinary copper loss; zinc gluconate blocks copper absorption from the gut. UDA (ursodeoxycholic acid): lowers the harmful chenodeoxycholic acid and promotes bile flow. Acetylcysteine: adjunct for acute liver damage, including acetaminophen toxicosis in cats; also prevents contrast-media nephrotoxicity.","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":85},{"id":"exam2-objective-086","lecture":"Lecture 17","section":"GI pharmacology","number":14,"q":"Two drugs for hepatic encephalopathy and how they work?","answer":"Lactulose: not metabolized; gut bacteria acidify the colon, so NH₃ becomes NH₄⁺ and is not absorbed. Rifaximin: unabsorbed antibiotic that reduces urease-positive bacteria, so less gut NH₃. (Metronidazole can be tried but is absorbed.)","note":null,"source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":86},{"id":"exam2-objective-087","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":1,"q":"Know: what drugs alone can address","answer":"Uncontrollable situational anxieties, compulsive behaviors and cognitive dysfunction can be treated with drugs alone. Everything else: rule out disease first (urine marking and seizures are big clues), then training, with drugs as an adjunct.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":87},{"id":"exam2-objective-088","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":2,"q":"Which neurotransmitter underlies most behavior problems and is the target of most drugs?","answer":"Serotonin (5-HT), the \"kingpin.\" Priority: 5-HT > dopamine > norepinephrine.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":88},{"id":"exam2-objective-089","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":3,"q":"Three intervention points for modulating it?","answer":"Enzymes (MAO), reuptake, and receptors. (GABA can only be changed at the receptor.)","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":89},{"id":"exam2-objective-090","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":4,"q":"Why is combination therapy not recommended?","answer":"Transmitter crossover causes side effects (serotonin syndrome risk). Combination only for refractory cases.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":90},{"id":"exam2-objective-091","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":5,"q":"Know the general characteristics of the four veterinary-labeled drugs (tradename in parentheses or yellow- highlighted)","answer":"Selegiline (Anipryl): MAO-B inhibitor; cognitive dysfunction in old dogs; monotherapy. Clomipramine (Clomicalm): TCA, blocks serotonin (most selective TCA) and norepinephrine reuptake; dog separation anxiety, compulsive disorders, cat urine marking; pro-drug (not for liver patients), cardiotoxic (not for geriatric, CV disease or glaucoma). Fluoxetine (Reconcile): SSRI; many dog and cat uses with minimal side effects; separation anxiety; cribbing in horses; cat spraying. Mirtazapine (Mirataz): 5-HT antagonist; transdermal gel on the ear for appetite in cats; probably the least cardiotoxic. ⚠ Confirm with him that these are the four he highlighted in yellow.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":91},{"id":"exam2-objective-092","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":6,"q":"Which drug treats cribbing in horses?","answer":"Fluoxetine (can go in the feed; not bitter).","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":92},{"id":"exam2-objective-093","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":7,"q":"Know: serotonin and aggression","answer":"Most of these drugs raise serotonin, and elevated serotonin is associated with aggression. They are not for treating aggression and can turn an anxious, subservient or compulsive animal aggressive.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":93},{"id":"exam2-objective-094","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":8,"q":"What is serotonin syndrome, when is it likely, and how is it treated?","answer":"A toxic buildup of serotonin. Likely with high-dose SSRIs or TCAs, combinations of MAOIs, SSRIs, TCAs and 5-HT agonists (SSRI + trazodone less likely), proserotonergic supplements (St. John's wort, SAMe, tryptophan), tyramine foods with an MAOI (dried meats, nuts, cheese, pickles, bananas), and other drugs (tramadol or any opioid, linezolid, metoclopramide). Treatment: mild = stop the serotonergic drugs and supplements. Severe = cyproheptadine (serotonin receptor blocker), diazepam or phenobarbital for seizures and tremors, fluids, cooling for fever. Survivors look normal in about 36 hours.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":94},{"id":"exam2-objective-095","lecture":"Lecture 18","section":"Behavior-modifying drugs (monoamine modulators)","number":9,"q":"Main cognitive dysfunction drug?","answer":"Selegiline (Anipryl), for geriatric dogs (anecdotally cats). The one to memorize; use as monotherapy.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":95},{"id":"exam2-objective-096","lecture":"Lecture 18","section":"Behavior-modifying benzodiazepines (BDZs)","number":1,"q":"Know: midazolam","answer":"The only BDZ that MUST be injected. (All others bind soft plastics, so no IV fluids.)","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":96},{"id":"exam2-objective-097","lecture":"Lecture 18","section":"Behavior-modifying benzodiazepines (BDZs)","number":2,"q":"Know: alprazolam","answer":"Short-acting BDZ for certain anxieties (fear and aggression in dogs, thunderstorm phobia with clomipramine, night anxiety); the most important of the short group.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":97},{"id":"exam2-objective-098","lecture":"Lecture 18","section":"Behavior-modifying benzodiazepines (BDZs)","number":3,"q":"Know: diazepam","answer":"Long-acting BDZ for certain anxieties and status epilepticus; the most important of the long group.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":98},{"id":"exam2-objective-099","lecture":"Lecture 18","section":"Behavior-modifying benzodiazepines (BDZs)","number":4,"q":"Why not use diazepam in cats for behavior?","answer":"Risk of fatal idiopathic hepatic necrosis with long-term use. 🎤    One or short-term doses are fine.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":99},{"id":"exam2-objective-100","lecture":"Lecture 18","section":"Behavior-modifying benzodiazepines (BDZs)","number":5,"q":"Know: BDZs are not first choice","answer":"Tolerance and dependence (do not stop abruptly). They are the \"I don't care\" drugs; side effects are sedation, motor problems, and disinhibition aggression in dogs.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":100},{"id":"exam2-objective-101","lecture":"Lecture 18","section":"Behavior-modifying benzodiazepines (BDZs)","number":6,"q":"Name of the GABA receptor antagonist and when you use it","answer":"Flumazenil: blocks the BDZ site; reverses midazolam cardiovascular effects and BDZ overdoses in any species. It can cause seizures, especially with a TCA or SSRI.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":101},{"id":"exam2-objective-102","lecture":"Lecture 18","section":"Behavior-modifying benzodiazepines (BDZs)","number":7,"q":"Know: alfaxalone","answer":"A neurosteroid that is an allosteric GABA-A modulator; used as a swine sedative and for anesthesia induction. A poor anticonvulsant because it needs endogenous GABA.","note":"The uploaded source combines instructor wording with additional notes; several statements about aggression, serotonin and combinations are oversimplified. Compare with clinical behavior references.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":102},{"id":"exam2-objective-103","lecture":"Lecture 19","section":"Anticonvulsants (1st study guide)","number":1,"q":"Two NTs involved in epilepsy?","answer":"GABA (inhibitory) and glutamate (excitatory). Seizures are a synchronous imbalance between them.","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":103},{"id":"exam2-objective-104","lecture":"Lecture 19","section":"Anticonvulsants (1st study guide)","number":2,"q":"Drug of choice for status epilepticus?","answer":"Diazepam (a BDZ) IV every 15 minutes until seizures stop, direct by catheter (it sticks to soft plastic). IM or rectal if the patient is shaking violently. Use midazolam for a CRI. Fine in cats for status epilepticus because use is short- term.","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":104},{"id":"exam2-objective-105","lecture":"Lecture 19","section":"Anticonvulsants (1st study guide)","number":3,"q":"Know: other options if the first choice fails","answer":"In order: diazepam (3–4 doses) → phenobarbital IV → (after 20 minutes) pentobarbital IV (if it works, think strychnine) → propofol CRI. Midazolam (CRI) and levetiracetam are other options. If all fail: ketamine bolus, dexmedetomidine bolus, then CRI of both with mild hypothermia.","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":105},{"id":"exam2-objective-106","lecture":"Lecture 19","section":"Anticonvulsants (1st study guide)","number":4,"q":"MOAs of BDZs, barbiturates, levetiracetam","answer":"BDZs: bind the GABA-A receptor and enhance GABA-mediated chloride influx. Barbiturates (phenobarbital, pentobarbital): activate the GABA receptor. Levetiracetam: binds a glutamate vesicle protein and blocks glutamate release. (Propofol activates GABA and blocks the glutamate receptor.)","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":106},{"id":"exam2-objective-107","lecture":"Lecture 19","section":"Anticonvulsants (1st study guide)","number":5,"q":"Drug for preventing feline epilepsy?","answer":"Phenobarbital (also the standard for dogs).","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":107},{"id":"exam2-objective-108","lecture":"Lecture 19","section":"Anticonvulsants (1st study guide)","number":6,"q":"Active ingredient in most euthanasia solutions?","answer":"Pentobarbital.","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":108},{"id":"exam2-objective-109","lecture":"Lecture 19","section":"Anticonvulsants (1st study guide)","number":8,"q":"Major side effect in dogs on phenobarbital plus KBr?","answer":"Pancreatitis.","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":109},{"id":"exam2-objective-110","lecture":"Lecture 19","section":"Anticonvulsants (1st study guide)","number":9,"q":"Major side effect in cats on KBr?","answer":"Bronchitis (cough). \"Coughing cat + bromide = bronchitis.\"","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":110},{"id":"exam2-objective-111","lecture":"Lecture 19","section":"Anticonvulsants (2nd study guide)","number":1,"q":"Number-one rule of combination anticonvulsant therapy?","answer":"Never use two drugs with the same MOA (so imepitoin should not be added to phenobarbital, since both are GABA agonists).","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":111},{"id":"exam2-objective-112","lecture":"Lecture 19","section":"Anticonvulsants (2nd study guide)","number":2,"q":"MOAs and uses of levetiracetam and primidone","answer":"Levetiracetam: inhibits glutamate release (glutamate vesicle protein). Effective with few side effects; needs three times daily dosing (once daily in horses); no blood- level monitoring, so good for fractious dogs; a good add-on to phenobarbital or KBr, and an option in status epilepticus. Primidone: a pro-drug converted in the liver to phenobarbital plus phenylethylmalonamide, both anticonvulsant; worth trying in phenobarbital-refractory seizures; will not work with liver impairment; his slide calls it the only drug approved for canine epilepsy. ⚠ Merck lists it as no longer recommended; confirm with him.","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":112},{"id":"exam2-objective-113","lecture":"Lecture 19","section":"Anticonvulsants (2nd study guide)","number":3,"q":"Preferred drug for euthanasia?","answer":"Pentobarbital (small animals). It stays stable in carcasses, so rendering plants refuse them and carnivores can be poisoned. Alternatives: ketamine + xylazine, propofol IV, isoflurane ± KCl.","note":"The status epilepticus sequence and fixed dosing instructions are not a substitute for current emergency guidelines. Verify primidone and bromide claims.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":113},{"id":"exam2-objective-114","lecture":"Lecture 20","section":"Alpha-2 drugs","number":1,"q":"Know: xylazine","answer":"The preferred sedative in ruminants. Oldest alpha-2 agonist; all major species except swine (no alpha-2 agonist works in swine).","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":114},{"id":"exam2-objective-115","lecture":"Lecture 20","section":"Alpha-2 drugs","number":2,"q":"Know: xylazine reversal","answer":"Yohimbine is the preferred reversal agent for xylazine (atipamezole or tolazoline also work).","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":115},{"id":"exam2-objective-116","lecture":"Lecture 20","section":"Alpha-2 drugs","number":3,"q":"Drug of choice for sedating a dog for allergy skin testing, unusual dosing, preferred antagonist?","answer":"Dexmedetomidine, because it does not interfere with the vasoactive responses to allergens. It is dosed by body surface area (mcg per square meter), not linear mg/kg. Preferred antagonist: atipamezole (yohimbine also works).","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":116},{"id":"exam2-objective-117","lecture":"Lecture 20","section":"Alpha-2 drugs","number":4,"q":"Know: romifidine","answer":"An equine-specific alpha-2 agonist for colic pain; longest duration of any alpha-2 agonist, very safe, not compatible with other drugs in a syringe.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":117},{"id":"exam2-objective-118","lecture":"Lecture 20","section":"Alpha-2 drugs","number":5,"q":"Know: medetomidine + vatinoxan","answer":"An alpha-2 agonist/antagonist combination; vatinoxan minimizes the side effects of the agonist.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":118},{"id":"exam2-objective-119","lecture":"Lecture 20","section":"Phenothiazines","number":1,"q":"Common MOA of phenothiazines?","answer":"Antagonists of the postsynaptic dopamine D2 receptor (like azaperone), giving sedation and tranquilization. Each drug adds more blockade (antihistamine, anticholinergic, anti-adrenergic, anti- serotonergic).","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":119},{"id":"exam2-objective-120","lecture":"Lecture 20","section":"Phenothiazines","number":2,"q":"Five potential uses of acepromazine?","answer":"(1) Anti-emesis (anti-ACh activity; maropitant is better for long-term use). (2) Exam room sedation and cooperation (can be dispensed before a routine visit; not controlled; avoid before an in-depth CV exam). (3) Travel sedation (airlines do not recommend it; risk of over-sedation and airway obstruction; fine for car rides). (4) Equine laminitis (anti-α1 vasodilation of the digital vessels, given IV). (5) Foal rejection (blocks D2 so prolactin is released, improving maternal bonding). Side effects: hypotension, equine persistent penile prolapse, seizures, poor temperature tolerance; Boxers and Bulldogs especially sensitive.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":120},{"id":"exam2-objective-121","lecture":"Lecture 20","section":"Phenothiazines","number":3,"q":"Genital side effect of acepromazine and how it helps when buying a horse?","answer":"Persistent penile prolapse in horses (stallions and geldings). When buying one, check for it: it can show up as a result of previous acepromazine use.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":121},{"id":"exam2-objective-122","lecture":"Lecture 20","section":"Phenothiazines","number":4,"q":"Unique use of cyproheptadine regarding serotonin?","answer":"It is a serotonin receptor blocker used to treat serotonin syndrome.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":122},{"id":"exam2-objective-123","lecture":"Lecture 20","section":"Opioids","number":1,"q":"Common MOA of opioids?","answer":"They activate opioid receptors (GPCRs: mu, kappa, delta). Postsynaptic activation dampens pain neurons; presynaptic activation blocks GABA release from pain-blocking neurons, which disinhibits them.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":123},{"id":"exam2-objective-124","lecture":"Lecture 20","section":"Opioids","number":2,"q":"Three most important side effects?","answer":"Respiratory depression, constipation, vomiting.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":124},{"id":"exam2-objective-125","lecture":"Lecture 20","section":"Opioids","number":3,"q":"Opioid vs opiate?","answer":"Opiates are natural compounds (morphine, codeine). Opioids are synthetic or semi- synthetic derivatives.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":125},{"id":"exam2-objective-126","lecture":"Lecture 20","section":"Opioids","number":4,"q":"Most useful opioid receptor antagonist?","answer":"Naloxone.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":126},{"id":"exam2-objective-127","lecture":"Lecture 20","section":"Opioids","number":6,"q":"Know how catnip works.","answer":"Nepetalactone appears to be a mu and kappa opioid receptor agonist; the euphoria is an autosomal dominant trait.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":127},{"id":"exam2-objective-128","lecture":"Lecture 20","section":"Opioids","number":7,"q":"Know: tramadol","answer":"An effective opioid analgesic in birds, questionable efficacy in dogs (though commonly prescribed for chronic use), and the opioid most likely to cause a seizure because of its effects on catecholamine reuptake channels.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":128},{"id":"exam2-objective-129","lecture":"Lecture 20","section":"Opioids","number":8,"q":"Know: butorphanol","answer":"A mixed agonist-antagonist: agonist at the kappa receptor, antagonist at mu. For mild-to- moderate pain (soft tissue, GI surgery); less respiratory depression than morphine. Very good for visceral pain in horses, does not appreciably inhibit gut motility, and is not excitatory in horses or cats. The mu antagonism lowers side effects and dependence, so it can be used longer post- operatively than morphine, and it can prevent wind-up. Sedative dose is lower than the analgesic dose. IV is best (IM and SQ irritate); oral works as an antitussive.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":129},{"id":"exam2-objective-130","lecture":"Lecture 20","section":"Opioids","number":9,"q":"Know: buprenorphine","answer":"A mu agonist (partial) and kappa antagonist; more potent than morphine, less dependence because of the kappa antagonism, and less respiratory depression (mu1 but not mu2 agonist). Approved in cats as 3 daily injections or a transdermal gel that lasts 4 days.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":130},{"id":"exam2-objective-131","lecture":"Lecture 20","section":"Opioids","number":10,"q":"Know: hydrocodone","answer":"An anti-tussive: mu activity suppresses the central cough center. The syrup contains homatropine, an anticholinergic that reduces respiratory secretions and also reduces the chance of abuse. Excellent bioavailability in dogs; prescribed for kennel cough.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":131},{"id":"exam2-objective-132","lecture":"Lecture 20","section":"Opioids","number":11,"q":"How to prevent wind-up?","answer":"Pre-emptive analgesia: give an opioid before (and after) surgery. Wind-up is NMDA-driven central sensitization after a painful event that can turn into chronic pain.","note":"Species-generalized alpha-2 claims, acepromazine seizure effects and opioid receptor/pharmacology statements require current clinical review.","source":"Uploaded Pharmacology Exam 2: Study Guide Answers and Practice Questions, Part 1 (Nov 14, 2026)","order":132}];
